	box[0][1] = m_min.y;
	box[0][2] = m_min.z;
	box[1][0] = m_max.x;
	box[1][1] = m_max.y;
	box[1][2] = m_max.z;
	reinterpret_cast<u32*>(box[1])[3] = all ? 0 : 224;
	hit->w = 0.0f;

