	f32 cy = vec.z * other->vec.x - vec.x * other->vec.z;
	f32 cz = vec.x * other->vec.y - vec.y * other->vec.x;
	out->vec.x = cx;
	out->vec.y = cy;
	out->vec.z = cz;
	out->w = 0.0f;

	f32 s = other->w;
	f32 tx = vec.x * s, ty = vec.y * s, tz = vec.z * s, tw = w * s;
	out->vec.x += tx;
	out->vec.y += ty;
	out->vec.z += tz;
	out->w += tw;

	s = w;
	tx = other->vec.x * s;
	ty = other->vec.y * s;
	tz = other->vec.z * s;
	tw = other->w * s;
	out->vec.x += tx;
	out->vec.y += ty;
	out->vec.z += tz;
	out->w += tw;

